const input = items[0].json;

const body = input.body || {};

let normalized = {
  source: null,
  extractionStatus: "failed",
  fullName: null,
  email: null,
  phoneNumber: null,
  companyName: null,
  estimatedBudget: null,
  message: null,
  // notes: null,
  // submittedAt: null
};


// =====================================
// Detect Tally
// =====================================
if (
  body.eventType === "FORM_RESPONSE" &&
  body.data &&
  Array.isArray(body.data.fields)
) {

  normalized.source = "Tally";

  const fields = {};

  body.data.fields.forEach(field => {
    fields[field.label] = field.value;
  });

  normalized.fullName = fields["Full Name"] || null;
  normalized.email = fields["Email"] || null;
  normalized.phoneNumber = fields["Phone Number"] || null;
  normalized.companyName = fields["Company Name"] || null;
  normalized.estimatedBudget = fields["Estimated Budget"] || null;
  normalized.message = fields["Message"] || null;
  // normalized.notes = fields["Message"] || null;

  // normalized.submittedAt =
  //   body.data.createdAt ||
  //   body.createdAt ||
  //   null;

  normalized.extractionStatus = "success";

}


// =====================================
// Detect Fillout
// =====================================
else if (
  body.formId &&
  body.submission &&
  Array.isArray(body.submission.questions)
) {

  normalized.source = "Fillout";

  const fields = {};

  body.submission.questions.forEach(question => {
    fields[question.name] = question.value;
  });


  normalized.fullName = fields["Full Name"] || null;
  normalized.email = fields["Email"] || null;
  normalized.phoneNumber = fields["Phone Number"] || null;
  normalized.companyName = fields["Company Name"] || null;
  normalized.estimatedBudget = fields["Estimated Budget"] || null;
  normalized.message = fields["Message"] || null;
  // normalized.notes = fields["Message"] || null;

  // normalized.submittedAt =
  //   body.submission.submissionTime ||
  //   body.submission.lastUpdatedAt ||
  //   null;

  normalized.extractionStatus = "success";

}


// =====================================
// Detect Google Forms
// =====================================
else if (
  body["Full Name"] ||
  body["Email"] ||
  body["Phone Number"]
) {

  normalized.source = "Google Forms";

  normalized.fullName = body["Full Name"] || null;
  normalized.email = body["Email"] || null;
  normalized.phoneNumber = body["Phone Number"] || null;
  normalized.companyName = body["Company Name"] || null;
  normalized.estimatedBudget = body["Estimated Budget"] || null;
  normalized.message = body["Message"] || null;
  // normalized.notes = body["Message"] || null;

  // normalized.submittedAt =
  //   body.timestamp ||
  //   null;

  normalized.extractionStatus = "success";

}

// Return normalized lead
return [
  {
    json: normalized
  }
];

const lead = items[0].json;

return [
  {
    json: {
      ...lead,

      // Metadata
      leadId: `LD-${Date.now()}`,
      status: "New",
      priority: "Medium",
      owner: "Unassigned",
      lastContacted: new Date().toISOString()
    },
  },
];

